//! Independent synthetic native outlines; no model or vendor source data.
use super::*;
use crate::boundary_clip_legacy::{ClipType, PolyFillType, PolyType};
fn union(rings: &[Vec<[i64; 2]>], modern: bool) -> Vec<Vec<[i64; 2]>> {
    let mut clipper = if modern {
        Clipper::new_global_merge()
    } else {
        Clipper::new()
    };
    for (index, ring) in rings.iter().enumerate() {
        let path: Vec<_> = ring.iter().map(|[x, y]| IntPoint::new(*x, *y)).collect();
        clipper
            .add_path(
                &path,
                if index == 0 {
                    PolyType::Subject
                } else {
                    PolyType::Clip
                },
                true,
            )
            .unwrap();
    }
    let mut out = Vec::new();
    assert!(
        clipper
            .execute(
                ClipType::Union,
                &mut out,
                PolyFillType::NonZero,
                PolyFillType::NonZero
            )
            .unwrap()
    );
    out.into_iter()
        .map(|ring| ring.into_iter().map(|p| [p.x, p.y]).collect())
        .collect()
}
#[test]
fn rounded_top_x_does_not_make_original_edges_collinear() {
    let mut sloped = super::super::types::TEdge::new();
    sloped.bot = IntPoint::new(-2, 5);
    sloped.top = IntPoint::new(0, 0);
    sloped.delta = IntPoint::new(2, -5);
    sloped.dx = -0.4;
    let mut vertical = super::super::types::TEdge::new();
    vertical.bot = IntPoint::new(0, 1);
    vertical.top = IntPoint::new(0, -20);
    vertical.delta = IntPoint::new(0, -21);
    vertical.dx = 0.;
    assert_eq!(top_x(&sloped, 1), 0);
    assert_eq!(top_x(&vertical, 1), 0);
    assert!(!slopes_equal_edges(&sloped, &vertical, false));
    assert!(super::super::clipper_base::slopes_equal4(
        IntPoint::new(0, 1),
        sloped.top,
        IntPoint::new(0, 1),
        vertical.top,
        false
    ));
}
#[test]
fn native_vertical_step_keeps_one_unit_corner() {
    let rings = vec![
        vec![[-200, 100], [-190, 100], [-195, 110]],
        vec![[0, -20], [0, 0], [-2, 5], [-12, -8]],
        vec![[0, 1], [0, -20], [12, -9]],
    ];
    let expected = vec![
        vec![[-195, 110], [-200, 100], [-190, 100]],
        vec![[0, 1], [0, 0], [-2, 5], [-12, -8], [0, -20], [12, -9]],
    ];
    for modern in [false, true] {
        assert_eq!(union(&rings, modern), expected);
    }
}
#[test]
fn twenty_legacy_native_primitive_outlines() {
    let cases: serde_json::Value = serde_json::from_str(LEGACY_GOLDENS).unwrap();
    let cases = cases.as_array().unwrap();
    assert_eq!(cases.len(), 20);
    for case in cases {
        let paths: Vec<Vec<[i64; 2]>> = serde_json::from_value(case["rings"].clone()).unwrap();
        let expected: Vec<Vec<[i64; 2]>> =
            serde_json::from_value(case["expected"].clone()).unwrap();
        assert_eq!(union(&paths, false), expected, "{}", case["name"]);
    }
}

