#[test]
fn explicit_global_sort_context_survives_clear() {
    use super::super::engine::SortContext;
    assert!(Clipper::new().sort_context == SortContext::Legacy);
    assert!(Clipper::default().sort_context == SortContext::Legacy);
    let mut global = Clipper::new_global_merge();
    assert!(global.sort_context == SortContext::Modern);
    global.clear();
    assert!(global.sort_context == SortContext::Modern);
}
